def fmt(x):return f'{x:.6g}'
def specificity_supported(table):
 for metric in ['D_A','D_B']:
  q=table[table.metric.eq(metric)]
  if len(q)!=1 or not (q.iloc[0]['mean']>0 and q.iloc[0].ci_low>0):return False
 return True

def clean_prose(text):
 replacements={'uses14':'uses 14','passed24/24':'passed 24/24','required20':'required 20','all72':'all 72','completed330':'completed 330','not20-update':'not 20-update','episode960':'episode 960','are172':'are 172','Adam.005':'Adam 0.005','Adam.001':'Adam 0.001','after10':'after 10','after20':'after 20','once at1,':'once at 1,','in50/0/50%':'in 50/0/50%','in25/50/25%':'in 25/50/25%','in50/40/10%':'in 50/40/10%','source960':'source 960','all331':'all 331','allfour':'all four','seeds6–19':'seeds 6–19','Screen:18':'Screen: 18','Confirmation:28':'Confirmation: 28','all20':'all 20','within330':'within 330','inner20':'inner 20','before14':'before 14','from2':'from 2','all14':'all 14','target330':'target update 330','fixed120':'fixed 120','strict C and':'strict C and','The selected prior does not':'The selected sharing-dominant prior does not'}
 for a,b in replacements.items():text=text.replace(a,b)
 return text

def main():
 selection=json.loads((OUT/'audit/selection_seal.json').read_text());stage='confirm' if selection['passed'] else 'screen';seeds=CONFIRM if selection['passed'] else SCREEN;f=read(stage+'_seed_outcomes');f=f[f.arm.ne('Baseline')];pairs=read(stage+'_paired_intervals');summary=read(stage+'_outcome_summary');arms=['A',selection['selected']] if selection['passed'] else list('ABC');doses=sorted(f.dose.unique());budget=json.loads((OUT/'audit/final_tables_verified.json').read_text());end=[]
